    h, w = len(g), len(g[0])
    # Background is dominant; extract the one non-background connected
    # component having the most cells as the stamp and its anchor.
    bg = max({v for row in g for v in row}, key=lambda v: sum(row.count(v) for row in g))
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x,g[y][x]))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and g[yy][xx]!=bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append(comp)
    template=max(comps,key=len)
    # In these tasks, the anchor is the uniquely colored cell in the seed,
    # if one exists; otherwise it is the middle cell of the horizontal stamp.
    values={v for _,_,v in template}
    unique=[v for v in values if sum(1 for _,_,z in template if z==v)==1]
    if unique:
        ar,ac,_=next(p for p in template if p[2]==unique[0])
    else:
        ar=template[0][0]; ac=(min(x for _,x,_ in template)+max(x for _,x,_ in template))//2
    offsets=[(r-ar,c-ac,v) for r,c,v in template]
    marks=[(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg and (r,c) not in {(y,x) for y,x,_ in template}]
    for r,c in marks:
        for dr,dc,v in offsets:
            y,x=r+dr,c+dc
            if 0<=y<h and 0<=x<w: g[y][x]=v
    return g

